sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }
    var gaBaseTable = new GlideAjax('BaseTableUtils');
    gaBaseTable.addParam('sysparm_name', 'checkMultipleUsers');
    gaBaseTable.addParam('sysparm_userid', newValue);
    gaBaseTable.getXMLAnswer(userCheck);

    //Type appropriate comment here, and begin script below

}

function userCheck(answer) {
    if (answer) {
        if (answer == true || answer == 'true') {
            g_form.clearValue("user");
            g_form.showFieldMsg("user", "This user is already allocated to another base. Please select a different user.", "error");
        }
        if (answer == false || answer == 'false') {
            // g_form.clearMessages();
            g_form.hideFieldMsg("user");
        }
    }
}
